def mteb_overall(scores: dict) -> float:
    """Mean of per-family means, rounded to 2 decimals.
    scores maps family name -> list of task scores for that family."""
    family_means = [sum(tasks) / len(tasks) for tasks in scores.values() if tasks]
    if not family_means:
        return 0.0
    overall = sum(family_means) / len(family_means)
    return round(float(overall), 2)

print(mteb_overall({
    "retrieval": [50.0, 60.0],
    "sts": [80.0],
    "classification": [70.0, 75.0, 65.0],
}))
